Here is the complete C program to solve this exercise. 

### Assumptions made based on the required output:
1. **Candidate Names:** Since each candidate has a first and last name, and names are on separate lines in the input, the program reads them pairwise (First Name + Last Name). (Total = 7 candidates).
2. **Invalid Votes:** Valid votes are between `1` and the number of candidates (`7`). Any vote strictly outside this range (like `8` or `9`) is considered invalid.
3. **Output Formatting:** The output is formatted carefully to match your exact requested output, including spacing and capitalization (e.g., `Nombre de votes annules` without an accent).

### C Code (`election.c`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CANDIDATES 50
#define MAX_NAME_LEN 50

int main() {
    FILE *inFile, *outFile;
    char firstName[MAX_CANDIDATES][MAX_NAME_LEN];
    char lastName[MAX_CANDIDATES][MAX_NAME_LEN];
    int votes[MAX_CANDIDATES] = {0};

    int numCandidates = 0;
    int totalVotes = 0;
    int validVotes = 0;
    int invalidVotes = 0;
    int vote;

    // 1. Open the input file for reading
    inFile = fopen("votes.txt", "r");
    if (inFile == NULL) {
        printf("Erreur : Impossible d'ouvrir le fichier votes.txt\n");
        return 1;
    }

    // 2. Read candidate names (Assuming each candidate has a First and Last name)
    while (numCandidates < MAX_CANDIDATES) {
        if (fscanf(inFile, "%49s", firstName[numCandidates]) != 1) break;
        if (fscanf(inFile, "%49s", lastName[numCandidates]) != 1) break;
        numCandidates++;
    }

    // 3. Read the votes
    int max_score = 0;
    while (fscanf(inFile, "%d", &vote) == 1) {
        totalVotes++;

        // Check if the vote is valid (between 1 and the number of candidates)
        if (vote >= 1 && vote <= numCandidates) {
            validVotes++;
            votes[vote - 1]++; // Increment the specific candidate's score
        } else {
            // Print invalid votes immediately to the console (standard output)
            printf("Vote invalide : %d\n", vote);
            invalidVotes++;
        }
    }
    fclose(inFile); // Done reading the input file

    // Find the maximum score to determine the winner(s)
    for (int i = 0; i < numCandidates; i++) {
        if (votes[i] > max_score) {
            max_score = votes[i];
        }
    }

    // 4. Open the output file for writing
    outFile = fopen("resultats.txt", "w");
    if (outFile == NULL) {
        printf("Erreur : Impossible de creer le fichier resultats.txt\n");
        return 1;
    }

    // 5. Write the results to the output file
    fprintf(outFile, "Nombre d'electeurs : %d\n", totalVotes);
    fprintf(outFile, "Nombre de votes valides : %d\n", validVotes);
    fprintf(outFile, "Nombre de votes annules : %d\n", invalidVotes);

    fprintf(outFile, "Candidat score\n");
    for (int i = 0; i < numCandidates; i++) {
        fprintf(outFile, "%s %s\t%d\n", firstName[i], lastName[i], votes[i]);
    }

    fprintf(outFile, "Les gagnants:\n");
    for (int i = 0; i < numCandidates; i++) {
        if (votes[i] == max_score) {
            fprintf(outFile, "%s %s\n", firstName[i], lastName[i]);
        }
    }

    fclose(outFile); // Done writing

    return 0;
}
```

### How to test this program:
1. Create a file named `votes.txt` in the same directory as your C program.
2. Paste the exact data provided into `votes.txt`:
```text
